PB = "OSH-39"; TL = "OSH-40"; DU = "OSH-45"; CA = "OSH-43"
Q = [
# ---------- 鉛中毒預防規則 ----------
(PB,"第2條",2,"鉛-適用",
 "鉛中毒預防規則所稱鉛作業，下列何者屬之？",
 ["鉛蓄電池製造修理解體中鉛之熔融鑄造研磨、含鉛塗料之剝除、通風不充分場所之鉛合金軟焊、含鉛設備內部作業等","鋁門窗製造修理拆卸中鋁材之裁切鑽孔研磨、防鏽塗料之噴塗、通風良好場所之錫線軟焊、密閉水塔內部作業等","水泥製品澆置養護拆模中砂石之攪拌篩選輸送、防水塗膜之塗布、開放式場所之鋼構銲接、地下管溝內部作業等","塑膠射出製造換模拆卸中粒料之乾燥混練研磨、脫模劑之噴灑、通風充分場所之熱風熔接、成品倉庫內部作業等"],"a",
 "第2條列十八款鉛作業：鉛之冶煉精煉、含鉛百分之三以上銅鋅冶煉、鉛蓄電池製造修理解體、鉛合金及鉛製品製造、電線電纜鉛被覆、鉛快削鋼注鉛、鉛化合物製造、鉛襯墊上光、橡膠塗料釉藥農藥玻璃等含鉛製造、通風不充分場所鉛合金軟焊、含鉛釉藥施釉烘燒、含鉛繪料繪畫烘燒、熔融鉛淬火退火砂浴、含鉛設備塗料之軋碎熔接切斷剝除、含鉛設備內部作業、轉印紙上粉、鉛字檢字排版、前述之清掃作業。",
 "Which is a 'lead operation' under the Lead Poisoning Prevention Rules?",
 ["Melting, casting or grinding lead in battery manufacture/repair, stripping lead paint, soft-soldering lead alloy in poorly ventilated places, work inside lead-contaminated equipment, etc.","Cutting, drilling or grinding aluminium in window-frame manufacture/repair, spraying anti-rust paint, soft-soldering tin wire in well-ventilated places, work inside sealed water tanks, etc.","Mixing, sieving or conveying aggregate in concrete casting and mould stripping, applying waterproof coatings, arc-welding steelwork in open areas, work inside underground pipe trenches, etc.","Drying, blending or grinding pellets in plastic injection moulding and mould changing, spraying release agents, hot-air welding in well-ventilated places, work inside finished-goods stores, etc."],
 "Article 2 lists 18 categories from smelting and battery work to lead paint removal, glazing, quenching in molten lead, typesetting and cleaning of such workplaces."),

(PB,"第3條",3,"鉛-定義",
 "鉛中毒預防規則所稱「鉛合金」指鉛佔合金重量百分之多少以上者？「通風不充分之場所」指室內對外開口面積未達底面積幾分之一或全面積百分之幾者？",
 ["百分之十以上；二十分之一或百分之三","百分之三以上；十分之一或百分之五","百分之五十以上；五分之一或百分之十","百分之一以上；三十分之一或百分之一"],"a",
 "第3條：鉛合金指鉛佔該合金重量百分之十以上；鉛混存物指鉛合金鉛化合物鉛混合物；作業時間短暫指每日作業時間一小時以內；臨時性作業指不超過三個月且一年內不再重覆；通風不充分之場所指室內對外開口面積未達底面積二十分之一以上或全面積百分之三以上者。",
 "A 'lead alloy' contains at least what percentage of lead by weight, and a 'poorly ventilated place' has openings below what fraction of floor area or what percentage of total area?",
 ["10%; one twentieth or 3%","3%; one tenth or 5%","50%; one fifth or 10%","1%; one thirtieth or 1%"],
 "Article 3: 10% lead; openings under 1/20 of floor area or 3% of total area."),

(PB,"第7條",2,"鉛-設施",
 "鉛蓄電池製造過程中，非以濕式作業方法從事鉛之研磨、製粉、混合、篩選、捏合之室內作業場所，應設置何種設備？",
 ["密閉設備或局部排氣裝置","整體換氣裝置或循環風扇","移動式集塵機或水霧噴頭","自然通風窗或排氣煙囪"],"a",
 "第7條：鉛蓄電池作業之熔融鑄造加工組配熔接熔斷極板切斷之室內場所設局部排氣裝置；非濕式之研磨製粉混合篩選捏合設密閉設備或局部排氣裝置；非濕式倒入取出粉狀鉛設局部排氣裝置及承受溢流設備；解體軋碎場所應與其他作業場所隔離；自動鑄造機防飛散；工作台設承受容器；人工搬運容器裝把手車輪；地面易於真空除塵或水洗；設儲存浮渣容器。第20條：此類氣罩應採包圍型。",
 "In battery manufacturing, indoor dry grinding, powdering, mixing, sieving or kneading of lead requires:",
 ["Enclosed equipment or local exhaust ventilation","General ventilation or recirculating ceiling fans","A mobile dust collector or water-mist nozzles","Natural ventilation windows or an exhaust stack"],
 "Article 7: enclosure or LEV for dry powder operations, LEV for melting/casting/welding, overflow catchers, isolation of crushing areas, splash guards, and easily cleaned floors; Article 20: enclosing hoods."),

(PB,"第24條",3,"鉛-免設",
 "下列何種鉛作業得免設置局部排氣裝置或整體換氣裝置？",
 ["與其他作業場所有效隔離且勞工不必經常出入之室內場所、作業時間短暫或臨時性作業、牆壁一半以上開放且四公尺內無障礙物之熔融鑄造場所、設排氣煙囪並以石灰覆蓋熔鉛表面者","與其他作業場所以布簾區隔而勞工每日出入之室內場所、作業時間達八小時之經常性作業、牆壁四分之一以上開放且二公尺內無障礙物之熔融鑄造場所、設電風扇並以砂土覆蓋熔鉛表面者","與辦公室相鄰而勞工得自由進出之室內作業場所、作業期間逾三個月之長期性作業、屋頂三分之一以上開放且六公尺內無障礙物之熔融鑄造場所、設抽風機並以清水覆蓋熔鉛表面者","與倉儲區共用而勞工經常往來之室內作業場所、每日作業四小時之固定性作業、牆壁五分之一以上開放且十公尺內無障礙物之熔融鑄造場所、設冷氣機並以木屑覆蓋熔鉛表面者"],"a",
 "第24條：與其他作業場所有效隔離而勞工不必經常出入之室內作業場所；作業時間短暫或臨時性作業；熔融鑄造等作業場所牆壁面積一半以上為開放且鄰近四公尺無障礙物者；熔融作業場所設利用溫熱上升氣流之排氣煙囟且以石灰覆蓋熔融鉛表面者；前三款勞工有遭鉛污染之虞時應提供防護具。",
 "Which lead operations may omit local exhaust or general ventilation?",
 ["Isolated rooms workers seldom enter, short or temporary work, melting areas with over half the walls open and no obstacles within 4 m, or melting with a thermal stack and lime cover","Rooms curtained off that workers enter daily, routine eight-hour work, melting areas with a quarter of the walls open and no obstacles within 2 m, or melting with a fan and a sand cover","Rooms next to offices that workers freely enter, long-term work over three months, melting areas with a third of the roof open and no obstacles within 6 m, or melting with a stack and water cover","Rooms shared with storage that workers pass through, fixed four-hour daily work, melting areas with a fifth of the walls open and no obstacles within 10 m, or melting with a cooler and sawdust"],
 "Article 24: the four exemptions, with PPE required for the first three when contamination is possible."),

(PB,"第27條",3,"鉛-集塵",
 "鉛或鉛合金熔融鑄造作業之熔爐或坩堝總容量未滿多少公升者，得免設集塵裝置？",
 ["五十公升","一百公升","二十公升","二百公升"],"a",
 "第27條：鉛作業之密閉設備及局部排氣裝置應設有效污染防制過濾式集塵設備或同等性能以上之集塵設備；熔爐或坩堝等總容量未滿五十公升者得免設集塵裝置。第49條：坩堝爐容量總計不滿五十公升且攝氏四百五十度以下熔融鑄造者僅適用部分條文。",
 "Melting or casting furnaces or crucibles with a total capacity below what volume are exempt from dust collectors?",
 ["50 liters","100 liters","20 liters","200 liters"],
 "Article 27: filter-type dust collectors required except for furnaces under 50 liters; Article 49: small furnaces below 450°C follow only limited provisions."),

(PB,"第31條",3,"鉛-設計",
 "雇主設置局部排氣裝置時應由何人設計？原始性能測試報告及相關文件應保存幾年？",
 ["經中央主管機關訓練合格之專業人員；十年","經勞動檢查機構備查之外部專業技師；三年","經設備製造廠商認可之現場工程人員；五年","經雇主指派之職業安全衛生管理員；一年"],"a",
 "第31條：密閉設備局部排氣裝置整體換氣裝置應由專業人員妥為設計並維持性能；設置局部排氣裝置應指派或委託經中央主管機關訓練合格之專業人員設計並製作設計報告書；設置完成後實施原始性能測試並製作報告書，文件紀錄保存十年；化學排氣櫃型式不受限制；改裝時亦同（性能無顯著影響者除外）。第31條之1：資格訓練準用特定化學物質危害預防標準第38條及第38條之1。",
 "Local exhaust ventilation must be designed by whom, and how long are the initial performance test reports kept?",
 ["Professionals trained and certified by the central authority; 10 years","External engineers recorded with the labor inspection agency; 3 years","Site engineers approved by the equipment manufacturer's agent; 5 years","Occupational safety and health officers appointed by the employer; 1 year"],
 "Article 31: certified designers with design and initial performance test reports kept 10 years (fume hoods exempt); Article 31-1 refers to the specified chemical standards for qualifications."),

(PB,"第32條",3,"鉛-換氣量",
 "於通風不充分場所從事鉛合金軟焊作業設置整體換氣裝置時，其換氣量應為每一從事鉛作業勞工平均每分鐘多少立方公尺以上？",
 ["一．六七立方公尺","零．五立方公尺","三立方公尺","十立方公尺"],"a",
 "第32條：從事第2條第2項第10款（通風不充分場所鉛合金軟焊）作業設置整體換氣裝置之換氣量，應為每一從事鉛作業勞工平均每分鐘一．六七立方公尺以上。第30條：局部排氣裝置應於作業時間內有效運轉並降低鉛塵濃度至容許暴露標準以下。",
 "General ventilation for soft-soldering lead alloy in poorly ventilated places must supply per worker at least:",
 ["1.67 m³ per minute","0.5 m³ per minute","3 m³ per minute","10 m³ per minute"],
 "Article 32: 1.67 m³/min per lead worker; Article 30: LEV must run during work and keep lead dust below the PEL."),

(PB,"第34條",2,"鉛-休息室",
 "雇主使勞工從事鉛作業時，應於作業場所外設置休息室，其出入口應如何？",
 ["設置沖洗用水管或充分濕潤之墊蓆以清除足部鉛塵，並於入口設置清除鉛塵用毛刷或真空除塵機","設置吹氣風管或完全乾燥之棕墊以拍除足部鉛塵，並於出口設置清除鉛塵用抹布或壓縮空氣槍","設置紫外線燈管或持續加熱之地墊以蒸除足部鉛塵，並於入口設置量測鉛塵用試紙或警示標誌","設置人員感應門或防滑之地磚以阻隔足部鉛塵，並於走道設置收集鉛塵用網籃或落塵承接盤"],"a",
 "第34條：休息室出入口應設沖洗用水管或充分濕潤之墊蓆清除足部鉛塵，入口設毛刷或真空除塵機；地面易於真空除塵或水洗；進入休息室前應清除工作衣上鉛塵並揭示。第35條：處理粉狀鉛者應設淋浴設備；第36條：每日以水沖洗或真空除塵清潔作業場所休息室餐廳一次以上；第37條：備置指甲刷肥皂等盥洗設備；第39條：設專用洗衣設備。",
 "Rest rooms for lead workers must be outside the work area, with entrances fitted with:",
 ["Washing hoses or wet mats to remove lead dust from feet, plus brushes or vacuum cleaners at the entrance","Air blow guns or dry coir mats to beat lead dust off feet, plus rags or compressed air lines at the exit","UV lamps or heated floor mats to bake lead dust off feet, plus test papers or warning signs at the entrance","Sensor doors or anti-slip tiles to block lead dust from feet, plus catch baskets or drip trays along the aisle"],
 "Article 34; Articles 35–39: showers for powder handling, daily washing, nail brushes and soap, and dedicated laundry facilities."),

(PB,"第40條",2,"鉛-作業主管",
 "鉛作業主管應執行之事項，下列何者正確？",
 ["採取措施預防勞工遭受鉛污染、決定作業方法並指揮、保存每月檢點局部排氣裝置一次以上之紀錄、監督防護具使用","採取措施提高現場作業產量、核定加班時數並排班、保存每年檢點局部排氣裝置一次以上之紀錄、監督出勤紀錄簽核","採取措施降低機具耗損成本、編列採購預算並議價、保存每半年檢點整體換氣裝置一次以上之紀錄、監督制服換洗","採取措施協調勞資爭議事項、辦理團體協約並簽署、保存每季檢點消防滅火設備一次以上之紀錄、監督餐廳清潔"],"a",
 "第40條：雇主應指派現場作業主管擔任鉛作業主管，執行採取必要措施預防勞工遭受鉛污染、決定作業方法並指揮勞工作業、保存每月檢點局部排氣裝置及其他預防健康危害裝置一次以上之紀錄、監督勞工確實使用防護具。第44條：應公告鉛作業場所禁止飲食或吸菸。",
 "The lead work supervisor must:",
 ["Prevent lead contamination, decide methods and direct work, keep records of at least monthly LEV checks, and supervise PPE use","Raise site output, approve overtime and set rosters, keep records of at least annual LEV checks, and supervise attendance sign-off","Cut machine wear costs, draw up purchase budgets and bargain, keep records of half-yearly general ventilation checks, and supervise uniforms","Mediate labor disputes, conclude collective agreements and sign, keep records of at least quarterly fire equipment checks, and supervise canteens"],
 "Article 40: the four duties; Article 44: no eating or smoking in lead workplaces."),

(PB,"第45條",2,"鉛-防護具",
 "從事鉛冶煉、砂浴攪砂、非濕式剝除含鉛塗料、含鉛設備內部作業、乾燥作業、集塵濾布更換等作業時，雇主應如何？",
 ["置備適當之呼吸防護具並訂定計畫使勞工確實遵守；防護具應專用保管並禁止攜入鉛作業場所以外","置備適當之防墜安全帶並公告規則使勞工自行選用；防護具得混合保管並開放攜至鉛作業場所以外","置備一般之棉紗口罩並口頭宣導使勞工視情況配戴；防護具由勞工自備並得攜回住所自行清洗","置備通用之耳塞耳罩並列入年度計畫使勞工參考；防護具與工作服共同存放並可攜往餐廳休息室"],"a",
 "第45條：對冶煉精煉鉛化合物製造及其清掃、砂浴攪砂換砂、非濕式剝除含鉛塗料、含鉛設備內部作業（並應置備防護衣著）、乾燥作業、集塵裝置濾布更換、鉛之軋碎熔接熔斷噴布、船舶儲槽等通風不充分場所鉛作業，應置備適當呼吸防護具並訂定計畫使勞工遵守；呼吸防護具及防護衣著應設專用保管設備與其他衣物隔離並禁止攜出。第46條：輸氣管面罩連續作業每次不得超過一小時；第47條：面罩入氣口置於新鮮空氣位置。",
 "For lead smelting, sand-bath stirring, dry stripping of lead paint, work inside lead equipment, drying or filter-bag replacement, the employer must:",
 ["Provide suitable respirators under a written program, stored separately and never taken outside the lead area","Provide fall-arrest harnesses under posted rules workers may opt into, stored together and freely taken outside","Provide ordinary cotton masks with verbal reminders to wear as workers see fit, self-bought and washed at home","Provide earplugs and earmuffs listed in the annual plan for reference, stored with work clothes and taken to canteens"],
 "Article 45: respirators (and protective clothing for equipment interiors) with a compliance plan and dedicated storage; Article 46: air-line masks limited to one hour per session."),

(PB,"第48條",2,"鉛-儲存",
 "雇主儲存粉狀之鉛、鉛混存物時應如何？漏洩時應如何處理？",
 ["使用不致漏洩之密閉容器儲存；漏洩時應即以真空除塵或以水清除","使用可透氣之網狀籃筐堆置；漏洩時應以壓縮空氣吹散並自然乾燥","使用敞開式之金屬淺盤盛裝；漏洩時得俟當日下班後再以掃帚清掃","使用一般之紙質提袋分裝；漏洩時應先灑上鋸屑再以乾布擦拭回收"],"a",
 "第48條：應使用不致漏洩之密閉容器適當儲存粉狀鉛及鉛混存物；漏洩時應即以真空除塵或以水清除；塊狀鉛應適當儲存避免鉛塵污染。第41條：粉狀鉛倒入漏斗有溢漏時應令勞工立即停止作業（臨時性作業且已戴用有效呼吸防護具者除外）。",
 "Powdered lead must be stored how, and spills cleaned how?",
 ["In leak-proof sealed containers; by vacuum or water","In ventilated mesh baskets; blown off with compressed air","In open metal trays; swept with a broom after the shift","In ordinary paper carry bags; covered in sawdust and wiped"],
 "Article 48: sealed containers, vacuum or wet cleaning; Article 41: stop work immediately on powder spills unless temporary work with effective respirators."),

# ---------- 四烷基鉛中毒預防規則 ----------
(TL,"第3條",2,"四烷基鉛-定義",
 "四烷基鉛中毒預防規則所稱「四烷基鉛」包括下列何者？",
 ["四甲基鉛、四乙基鉛、一甲基三乙基鉛、二甲基二乙基鉛、三甲基一乙基鉛及含有上列物質之抗震劑","一氧化鉛、四氧化三鉛、鹼式碳酸鉛、鉻酸鉛、硫酸鉛及含有上列物質之防鏽顏料與塗料製品","四氯化碳、四氯乙烯、三氯乙烯、二氯甲烷、三氯乙烷及含有上列物質之金屬脫脂清洗溶劑","甲基汞、乙基汞、二甲基汞、氯化汞、硫化汞及含有上列物質之農用殺菌劑與防霉塗料"],"a",
 "第3條：四烷基鉛指四甲基鉛、四乙基鉛、一甲基三乙基鉛、二甲基二乙基鉛、三甲基一乙基鉛及含有上列物質之抗震劑；加鉛汽油指添加四烷基鉛之汽油；換氣裝置指藉動力輸入外氣置換儲槽地下室船艙坑井等內部空氣之設備。第2條：適用於混入汽油或導入儲槽、裝置修護拆卸、被污染儲槽處理、殘渣廢液處理、容器處理、研究試驗、污染清除等七類作業。",
 "'Tetraalkyl lead' under the Rules includes:",
 ["Tetramethyl lead, tetraethyl lead, methyl-triethyl lead, dimethyl-diethyl lead, trimethyl-ethyl lead and anti-knock agents containing them","Lead monoxide, red lead, basic lead carbonate, lead chromate, lead sulfate and the anti-rust pigments and coating products containing them","Carbon tetrachloride, tetrachloroethylene, trichloroethylene, dichloromethane and the metal degreasing cleaning solvents containing them","Methylmercury, ethylmercury, dimethylmercury, mercuric chloride, mercuric sulfide and the agricultural fungicides and coatings containing them"],
 "Article 3 definitions; Article 2 lists seven operation types from blending into gasoline to cleaning contaminated sites."),

(TL,"第5條",3,"四烷基鉛-混入作業",
 "從事將四烷基鉛混入汽油或導入儲槽之作業時，作業場所建築物之牆壁至少應有幾面為開放且能充分通風？應供給勞工何種防護具？",
 ["三面；不滲透性防護圍裙、長統手套、長靴及有機氣體用防毒面罩","一面；棉質工作圍裙、短棉手套、布鞋及粉塵用防塵口罩即可","二面；透氣性防護背心、半指手套、涼鞋及一般外科用醫療口罩","四面；防靜電實驗衣、乳膠手套、雨鞋及酸性氣體用濾毒罐面罩"],"a",
 "第5條：裝置構造應防止污染或吸入蒸氣；作業場所建築物牆壁至少三面開放且充分通風；抽吸四烷基鉛應完全吸盡並以汽油清洗栓密；供給不滲透性防護圍裙長統手套長靴及有機氣體用防毒面罩；作業場所與其他場所隔離；地面不滲透性易清除；設休息室盥洗淋浴設備；每日確認裝置狀況一次以上。",
 "For blending tetraalkyl lead into gasoline, at least how many walls of the building must be open for ventilation, and what PPE is required?",
 ["Three; impermeable apron, long gloves, boots and organic-vapor respirator","One; cotton work apron, short gloves, cloth shoes and a dust mask only","Two; breathable vest, fingerless gloves, sandals and a surgical mask","Four; anti-static lab coat, latex gloves, rain boots and an acid-gas mask"],
 "Article 5: three open walls, leak-proof equipment, impermeable PPE with organic-vapor respirators, isolation, impermeable floors, washing and shower facilities, daily equipment checks."),

(TL,"第7條",3,"四烷基鉛-儲槽",
 "處理四烷基鉛用儲槽內部作業時，應以何種氧化劑將儲槽內部充分氧化？並應指派幾人以上監視？",
 ["適當氧化劑如百分之五過錳酸鉀溶液；一人以上","適當還原劑如百分之十亞硫酸鈉溶液；不需監視","適當中和劑如百分之三氫氧化鈉溶液；二人以上","適當溶劑如百分之二十異丙醇水溶液；三人以上"],"a",
 "第7條：自儲槽抽出四烷基鉛後防止倒流；以汽油或煤油洗淨排出；使用適當氧化劑如百分之五過錳酸鉀溶液充分氧化並排出；開放人孔排放閥等開口；以水或水蒸氣清洗（水蒸氣時應接地）；作業前及作業期間以換氣裝置充分換氣；設緊急避難設施；指派監視人員一人以上；供給不滲透性防護衣著長統手套長靴防護帽及輸氣管面罩。第8條：加鉛汽油儲槽作業類似，換氣須將汽油濃度降至容許暴露標準以下。",
 "When working inside a tetraalkyl lead tank, which oxidizer is used to treat the interior, and how many watchers are required?",
 ["A suitable oxidizer such as 5% potassium permanganate solution; at least one","A suitable reducer such as 10% sodium sulfite solution; no watcher needed","A suitable neutralizer such as 3% sodium hydroxide solution; at least two","A suitable solvent such as 20% isopropyl alcohol solution; at least three"],
 "Article 7: drain and prevent backflow, wash with gasoline/kerosene, oxidize with 5% KMnO4, open all openings, rinse with water or steam (grounded), ventilate, emergency escape equipment, one watcher, impermeable PPE with air-line masks."),

(TL,"第13條",2,"四烷基鉛-清洗劑",
 "雇主使勞工從事清洗作業或供給勞工清洗手足身體之清洗劑時，不得使用何物？",
 ["加鉛汽油","中性肥皂","溫熱清水","洗手乳液"],"a",
 "第13條：雇主使勞工從事清洗作業或供給勞工清洗手足、身體之清洗劑時，不得使用加鉛汽油。第17條：作業完畢應供給肥皂洗淨雙手及被污染部分。第25條：作業場所應置備肥皂、洗眼液吸附劑急救藥品、氧化劑活性白土等防止擴散材料、整補材料。",
 "Employers must not use what as a cleaning agent for workers' hands or bodies?",
 ["Leaded gasoline","Neutral soap bar","Warm clean water","Hand wash lotion"],
 "Article 13; Article 17: soap after work; Article 25: soap, eyewash, absorbents, oxidizers and repair materials on site."),

(TL,"第16條",2,"四烷基鉛-作業主管",
 "四烷基鉛作業主管應每日確認何事？發現勞工身體或衣服被四烷基鉛污染時應如何？",
 ["確認換氣裝置運轉狀況；立即以肥皂或適當清洗劑洗除污染","確認出勤刷卡紀錄；立即以加鉛汽油或有機溶劑擦拭污染","確認當日產量報表；俟作業全部完畢後再更換工作衣即可","確認材料庫存數量；先行記錄並於次日健康檢查時再處理"],"a",
 "第16條：四烷基鉛作業主管（研究試驗作業免設）應決定作業方法並指揮、預防勞工污染或吸入、每日確認儲槽作業及污染清除作業之換氣裝置運轉狀況、監督防護具使用、有中毒之虞時採取必要措施、發現身體或衣服被污染時立即以肥皂或適當清洗劑洗除。第21條：每週確認通風設備運轉作業情形空氣流通效果及使用情形一次以上。",
 "The tetraalkyl lead work supervisor must check what daily, and what must be done when a worker's body or clothing is contaminated?",
 ["Ventilation equipment operation; wash off immediately with soap or a suitable cleanser","Attendance card records; wipe off immediately with leaded gasoline or organic solvent","Daily output reports; simply change work clothes after all the work has been finished","Material stock levels; record it first and deal with it at the next health examination"],
 "Article 16: daily ventilation checks, PPE supervision and immediate washing of contamination; Article 21: weekly confirmation of ventilation and work conditions."),

(TL,"第20條",2,"四烷基鉛-緊急",
 "四烷基鉛作業發生設備或換氣裝置故障、漏洩溢流或場所被污染致有中毒之虞時，雇主應如何？勞工得否自行退避？",
 ["即令停止作業並使勞工退避至安全場所；勞工在不危及他人安全下得自行停止作業退避並立即報告主管","即通知設備廠商到場檢修並繼續作業；勞工應待作業主管到場確認後始得停止作業退避並填寫紀錄","即開啟門窗加強自然通風後照常作業；勞工非經雇主書面同意不得自行停止作業退避或離開崗位","即報請勞動檢查機構派員複檢後處理；勞工須俟當日工作全部完成後始得退避並於次日報告主管"],"a",
 "第20條：設備或換氣裝置故障致降低失去效能、四烷基鉛漏洩或溢流、作業場所被污染時，雇主或工作場所負責人應即令停止作業並使勞工退避至安全場所；勞工在不危及其他工作者安全之情形下亦得自行停止作業及退避並立即向直屬主管報告；未確認完全清除前不得使相關勞工進入，但在職業安全衛生管理人員或作業主管指導下之搶救及必要作業者除外。",
 "When ventilation fails, tetraalkyl lead leaks or the area is contaminated, the employer must do what, and may workers retreat on their own?",
 ["Stop work and evacuate; workers may stop and retreat themselves if it endangers no one else, then report","Call the equipment vendor and keep working; workers may retreat only once the supervisor confirms, then log it","Open windows for natural ventilation and work as usual; workers may not retreat without written employer consent","Ask the inspection agency to re-inspect first; workers may retreat only after the day's work is complete, reporting next day"],
 "Article 20: stop-and-evacuate duty, workers' right to retreat, no re-entry until cleared except supervised rescue."),

(TL,"第23條",2,"四烷基鉛-面罩",
 "四烷基鉛作業勞工戴用輸氣管面罩之連續作業時間每次不得超過多久？防護具應保管於何處？",
 ["一小時；作業場所外之金屬材質保管設備並與其他衣物隔離","二小時；作業場所內之木質置物櫃並得與其他衣物混放","三十分鐘；更衣室內之塑膠收納箱並與其他衣物一併存放","四小時；勞工住所內之自備衣櫃並由勞工自行清洗保管"],"a",
 "第23條：戴用輸氣管面罩之連續作業時間每次不得超過一小時。第22條：面罩空氣入口置於新鮮空氣位置。第24條：每天作業前確認防護具狀況，防毒面罩吸收罐保持有效，作業完畢確認並清除污染；應於作業場所外設置存放防護具工作衣之金屬材質保管設備並與其他衣物隔離。",
 "Continuous work in an air-line mask is limited to how long, and where must PPE be stored?",
 ["1 hour; metal storage outside the work area, separated from other clothing","2 hours; wooden lockers inside the work area, mixed with other clothing","30 minutes; plastic bins in the changing room, stored with other clothing","4 hours; the worker's own wardrobe at home, washed and kept by the worker"],
 "Article 23: one hour; Article 24: daily PPE checks, effective cartridges, and separate metal storage outside the work area."),

(TL,"第26條",2,"四烷基鉛-儲藏",
 "儲藏四烷基鉛或加鉛汽油之容器及場所應如何？曾儲裝四烷基鉛之空容器應如何？",
 ["具栓蓋之牢固容器且桶蓋向上；場所防止無關人員進入並標示、蒸氣排除於室外、防漏洩措施；空容器密閉或置於室外一定場所並標示","具提把之輕便容器且桶蓋側放；場所開放供人員自由進出並免標示、蒸氣排放於室內、防日曬措施；空容器敞開或置於室內走道旁並標示","具透氣孔之塑膠容器且桶蓋倒置；場所僅設繩索圍籬並口頭告知、蒸氣以風扇稀釋、防塵措施；空容器加水或置於地下室角落並上鎖","具紙質襯裡之紙箱且開口朝下；場所張貼海報即可並免管制、蒸氣以活性碳吸附、防震措施；空容器壓扁或逕交清潔隊處理並登記"],"a",
 "第26條：應使用具有栓蓋之牢固容器並使桶蓋向上，儲藏場所應有防止無關人員進入之設施及標示、將蒸氣排除於室外、防止不慎漏洩之措施。第27條：曾儲裝四烷基鉛之空容器應予密閉或放置於室外一定場所並標示。第19條：禁止無關勞工進入作業及儲存場所。",
 "Containers and storage areas for tetraalkyl lead must be, and empty containers must be:",
 ["Sturdy capped containers stored cap-up; restricted, labeled and vented areas with leak precautions; empties sealed or placed outdoors in a marked area","Light handled containers stored cap-sideways; open unlabeled areas anyone may enter, vented indoors with sun precautions; empties left open by indoor aisles","Vented plastic containers stored cap-down; areas roped off with verbal notice, vapors fan-diluted with dust precautions; empties water-filled and locked in a basement","Lined paper cartons stored mouth-down; areas needing only a poster and no control, vapors carbon-adsorbed with shock precautions; empties crushed and given to refuse collectors"],
 "Articles 26–27; Article 19: unauthorized entry prohibited with posted notices."),

# ---------- 粉塵危害預防標準 ----------
(DU,"第3條",3,"粉塵-定義",
 "粉塵危害預防標準所稱「作業時間短暫」及「作業期間短暫」之定義為何？",
 ["每日作業不超過一小時；作業期間不超過一個月且終了後六個月內不再實施","每日作業不超過二小時；作業期間不超過三個月且終了後三個月內不再實施","每日作業不超過三十分鐘；作業期間不超過一週且終了後一個月內不再實施","每週作業不超過一日；作業期間不超過一年且終了後十二個月內不再實施"],"a",
 "第3條：作業時間短暫指同一特定粉塵發生源之特定粉塵作業每日不超過一小時；作業期間短暫指作業期間不超過一個月且確知自終了日起六個月內不再實施；臨時性作業指不超過三個月且一年內不再重覆；特定粉塵發生源指附表一乙欄所列處所；礦物等指地殼中土石岩石礦物及性質相同之人工固體物質。",
 "'Short daily work' and 'short-period work' under the Dust Hazard Standards mean:",
 ["No more than 1 hour per day; no more than 1 month and not repeated within 6 months after ending","No more than 2 hours per day; no more than 3 months and not repeated within 3 months after ending","No more than 30 minutes a day; no more than 1 week and not repeated within 1 month after ending","No more than 1 day per week; no more than 1 year and not repeated within 12 months after ending"],
 "Article 3 definitions; temporary work is under 3 months and not repeated within a year."),

(DU,"第6條",2,"粉塵-特定發生源",
 "雇主為防止特定粉塵發生源之粉塵發散，應依附表一乙欄所列每一特定粉塵發生源設置何種設備？",
 ["密閉設備、局部排氣裝置或維持濕潤狀態之設備等對應設備之一種或同等以上性能之設備","電風扇、循環空調機組或加裝隔音罩之設備等輔助設備之全部或較低性能之替代設備","自然通風窗、移動式抽風機或定期灑水之設備等臨時設備之任二種且不限性能之設備","集塵袋、靜電除塵機組或加熱乾燥之設備等後端設備之一種或較差性能之簡易設備"],"a",
 "第6條：應依附表一乙欄每一特定粉塵發生源分別設置該欄所列設備（密閉設備、局部排氣裝置、維持濕潤狀態、濕式衝擊式鑿岩機等）之任一種或具同等以上性能之設備。第7條：局部排氣裝置應設附表二所列型式以外之氣罩。第9條：磨床鼓式砂磨機等回轉機械應以全部包圍、覆蓋擴散方向或包圍回轉體部分之方式設氣罩。",
 "For each specified dust source in Annex 1 column B, the employer must install:",
 ["One of the corresponding controls such as enclosure, local exhaust or wetting equipment, or equipment of equal or better performance","All of the auxiliary items such as electric fans, packaged air conditioners or sound enclosures, or substitutes of lower performance","Any two temporary items such as natural ventilation windows, portable extractors or periodic water spraying, with no performance limit","One of the downstream items such as dust bags, electrostatic precipitators or heated drying units, or simple gear of poorer performance"],
 "Article 6; Article 7: hood types per Annex 2; Article 9: hoods for grinders and drum sanders."),

(DU,"第10條",2,"粉塵-一般作業",
 "對於特定粉塵作業以外之粉塵作業之室內作業場所，雇主應設置何種設備？例外為何？",
 ["整體換氣裝置或同等以上性能設備；臨時性作業、作業時間或期間短暫且供給適當呼吸防護具者除外","密閉設備或同等以上性能之隔離設備；經常性作業、作業時間長達八小時且供給一般棉紗口罩者除外","局部排氣裝置或較低性能之替代設備；所有室內作業、作業時間或期間短暫但未供給防護具者除外","自然通風窗或移動式抽風設備即可；戶外作業、作業期間逾三個月且已實施特殊健康檢查者除外"],"a",
 "第10條：非特定粉塵作業之室內作業場所應設整體換氣裝置或同等以上性能設備，但臨時性作業、作業時間短暫或作業期間短暫且供給適當呼吸防護具者不在此限。第11條：坑內作業場所（平水坑除外）應設具動力輸入外氣之換氣裝置。第11條之1：密閉設備局部排氣整體換氣應由專業人員設計並維持性能。",
 "For indoor dust work that is not 'specified dust work', the employer must install what, with what exception?",
 ["General ventilation or equivalent; except temporary or short work where suitable respirators are provided","Enclosure or equivalent isolation; except routine eight-hour work where ordinary cotton masks are provided","Local exhaust or lower-performance substitutes; except all indoor work and short work with no respirators","Natural windows or portable extractors; except outdoor work over three months where health checks are done"],
 "Article 10; Article 11: powered fresh-air ventilation in mines; Article 11-1: professional design."),

(DU,"第13條",3,"粉塵-小型設備",
 "使用直徑小於幾公分之研磨輪、每小時能力小於幾公斤之粉碎機、篩選面積小於幾平方公分之篩選機、內容積小於幾公升之混合機從事特定粉塵作業，雇主設整體換氣並使勞工使用呼吸防護具時，得不適用第6條？",
 ["三十公分；二十公斤；七百平方公分；十八公升","五十公分；五十公斤；一千平方公分；五十公升","十公分；十公斤；一百平方公分；五公升","一百公分；一百公斤；二千平方公分；一百公升"],"a",
 "第13條：使用前直徑小於三十公分之研磨輪、搗碎或粉碎最大能力每小時小於二十公斤之機器、篩選面積小於七百平方公分之篩選機、內容積小於十八公升之混合機從事特定粉塵作業，雇主於室內設整體換氣裝置（坑內設換氣裝置）並使勞工使用適當呼吸防護具者，得不適用第6條。第12條：臨時性作業或作業時間期間短暫且供給呼吸防護具者亦不適用第6條。",
 "Specified dust work with small equipment is exempt from Article 6 (with general ventilation and respirators) when the grinding wheel is under, crusher capacity under, sieve area under, mixer volume under:",
 ["30 cm; 20 kg/h; 700 cm²; 18 L","50 cm; 50 kg/h; 1,000 cm²; 50 L","10 cm; 10 kg/h; 100 cm²; 5 L","100 cm; 100 kg/h; 2,000 cm²; 100 L"],
 "Article 13 thresholds; Article 12 exempts temporary and short work with respirators."),

(DU,"第14條",3,"粉塵-免除申請",
 "設置第6條規定設施顯有困難時，雇主得向何機關申請免除？應檢附何文件？",
 ["勞動檢查機構；免適用設施許可申請書、比例百分之一以上之作業場所略圖、工作計畫書","中央主管機關；免適用設施備查報告書、比例千分之一以上之作業場所照片、營業登記證","直轄市勞工局；設施變更登記申請書、比例百分之五以上之廠區配置圖、勞工名冊清單","當地衛生主管機關；設施豁免核定申請表、比例十分之一以上之建築平面圖、健檢紀錄"],"a",
 "第14條：依構造作業性質設置第6條設施顯有困難者，得填具免適用設施許可申請書、比例在百分之一以上之作業場所略圖、工作計畫書向勞動檢查機構申請免除；作業不適於原許可時應書面報告，檢查機構得取銷許可。",
 "When Article 6 controls are clearly impracticable, the employer may apply for exemption to whom, with what documents?",
 ["The labor inspection agency; exemption application form, site sketch at 1:100 or larger, and work plan","The central authority; exemption recordation report, site photos at 1:1,000 or larger, and business registration","The municipal labor bureau; facility change form, plant layout at 1:20 or larger, and a worker roster","The local health authority; facility waiver form, building floor plan at 1:10 or larger, and health records"],
 "Article 14: application to the inspection agency with form, sketch (scale ≥ 1%) and work plan; permits may be revoked if conditions change."),

(DU,"第15條",2,"粉塵-局排",
 "粉塵作業局部排氣裝置之設置規定，下列何者正確？",
 ["氣罩設於每一粉塵發生源且外裝型儘量接近發生源、導管儘量縮短肘管減少並設清潔口測定孔、排氣機置於空氣清淨裝置後、排氣口設於室外","氣罩設於作業場所出入口且外裝型儘量遠離發生源、導管儘量加長肘管增多以利緩衝、排氣機置於空氣清淨裝置前、排氣口設於室內","氣罩僅設於主要通道上方且包圍型儘量遠離發生源、導管長度不限但不得開設清潔口測定孔、排氣機置於氣罩內部、排氣口設於休息室","氣罩設於各層樓梯間且外裝型緊貼牆面設置、導管以軟管彎繞配置並免設清潔口測定孔、排氣機置於屋頂水塔旁、排氣口設於地下室"],"a",
 "第15條：氣罩宜設於每一粉塵發生源，外裝型儘量接近發生源；導管長度儘量縮短肘管數儘量減少並於適當位置開設清潔口及測定孔；排氣機置於空氣清淨裝置後；排氣口設於室外（移動式或設過濾除塵靜電除塵者除外）。第16條：粉塵作業時間內不得停止運轉且不得阻礙。",
 "Which is correct for local exhaust ventilation in dust work?",
 ["Hoods at every source (exterior hoods close to the source), short ducts with few elbows plus cleanout and test ports, fan after the air cleaner, exhaust outlet outdoors","Hoods at the workplace entrance (exterior hoods far from the source), long ducts with many elbows to buffer the flow, fan before the air cleaner, exhaust outlet indoors","Hoods only above the main aisle (enclosing hoods far from the source), ducts of any length with no cleanout or test ports, fan inside the hood, exhaust outlet in the rest room","Hoods in each stairwell (exterior hoods pressed flat to the wall), flexible ducts coiled around with no cleanout or test ports, fan by the roof water tank, exhaust outlet in the basement"],
 "Article 15; Article 16: must run throughout dust work without obstruction."),

(DU,"第22條",2,"粉塵-清掃",
 "雇主對室內粉塵作業場所至少每日應清掃幾次？每月應以何種方法清除地面設備？",
 ["每日一次以上；每月以真空吸塵器或水沖洗等不致飛揚之方法","每週一次以上；每季以掃帚或壓縮空氣吹除等快速清潔之方法","每月一次以上；每年以乾布擦拭或鼓風機吹掃等簡便之方法","每季一次以上；每半年以鏟除或高壓氣體噴吹等徹底之方法"],"a",
 "第22條：室內粉塵作業場所至少每日清掃一次以上；至少每月定期使用真空吸塵器或以水沖洗等不致發生粉塵飛揚之方法清除地面設備，顯有困難且已供給呼吸防護具者除外。第21條：公告禁止飲食吸菸。第20條：應指定粉塵作業主管監督。第19條：隨時確認通風設備運轉作業情形空氣流通及粉塵狀況並通告注意事項。",
 "Indoor dust workplaces must be cleaned at least how often, and monthly cleaning must use what method?",
 ["Daily; vacuum cleaners or water flushing that does not raise dust","Weekly; brooms or compressed air blow-guns for quick cleaning","Monthly; dry cloth wiping or blower purging as a simple method","Quarterly; scraping or high-pressure gas jets for thorough cleaning"],
 "Article 22; Articles 19–21: continuous checks, a dust work supervisor, and no eating or smoking."),

(DU,"第23條",2,"粉塵-防護具",
 "從事附表一丙欄所列作業（如坑外衝擊式鑿岩、手提式動力工具切斷研磨岩石金屬、內部熔斷電焊等）時，雇主應如何？",
 ["提供並令勞工使用適當之呼吸防護具，但發生源已設有效密閉設備局部排氣或維持濕潤者除外","提供並令勞工使用一般之棉紗口罩，但發生源已設電風扇整體換氣或定期灑水降溫者除外","提供並任由勞工自行選用防塵面罩，但作業時間短暫或已實施特殊健康檢查及問診者除外","提供並令勞工使用防護眼鏡及手套，但發生源已加裝隔音罩或於周邊設置警示標示者除外"],"a",
 "第23條：從事附表一丙欄所列作業應提供並令勞工使用適當呼吸防護具，但粉塵發生源設有效之密閉設備、局部排氣裝置或維持濕潤狀態者不在此限。第24條：輸氣管面罩連續作業每次不得超過一小時。第17、18條：濕式鑿岩機應有效給水，濕潤設備於作業時保持濕潤。",
 "For operations in Annex 1 column C (e.g., outdoor impact rock drilling, handheld power tool cutting/grinding of rock or metal, welding or cutting inside enclosed spaces), the employer must:",
 ["Provide and enforce suitable respirators, unless the source has effective enclosure, LEV or wetting","Provide and enforce ordinary cotton masks, unless the source has fans, general ventilation or spraying","Provide and let workers freely choose dust masks, unless the work is short or special health checks are done","Provide and enforce safety goggles and gloves, unless the source has sound enclosures or warning signs posted"],
 "Article 23; Article 24: air-line masks one hour per session; Articles 17–18: wet drills and wetting equipment must be kept working."),

# ---------- 危害性化學品評估及分級管理辦法 ----------
(CA,"第2條",2,"化學品分級-定義",
 "危害性化學品評估及分級管理辦法所稱「分級管理」係指？",
 ["依化學品健康危害及暴露評估結果評定風險等級，並分級採取對應之控制或管理措施","依化學品採購價格及供應商評鑑結果評定採購等級，並分級簽訂對應之供貨合約","依化學品毒性分類及運送距離結果評定標示等級，並分級張貼對應之危害警示圖式","依化學品最大儲存量及廠區面積評定申報等級，並分級向主管機關辦理登記備查"],"a",
 "第2條：暴露評估指以定性半定量或定量方法評量或估算勞工暴露於化學品之健康危害情形；分級管理指依化學品健康危害及暴露評估結果評定風險等級並分級採取對應之控制或管理措施。第4條：製造處置使用符合 CNS 15030 具健康危害之化學品應評估危害及暴露程度、劃分風險等級並採取分級管理措施。",
 "'Tiered (banding) management' under the Regulations means:",
 ["Rating risk levels from health hazard and exposure assessment and applying corresponding controls by level","Rating purchase levels from unit price and supplier appraisal and signing corresponding supply terms by level","Rating labeling levels from toxicity class and haulage distance and posting corresponding hazard pictograms","Rating reporting levels from maximum storage and plant area and registering with the competent authority"],
 "Article 2; Article 4 requires assessment, risk rating and tiered controls for CNS 15030 health-hazardous chemicals."),

(CA,"第3條",3,"化學品分級-優先適用",
 "危害性化學品評估及分級管理辦法所定化學品，應優先適用哪些法規之危害控制規定？",
 ["特定化學物質危害預防標準、有機溶劑中毒預防規則、四烷基鉛中毒預防規則、鉛中毒預防規則及粉塵危害預防標準","消防法及其施行細則、公共危險物品管理辦法、毒性及關注化學物質管理法、廢棄物清理法及空氣污染防制法","建築法及建築技術規則、室內空氣品質管理法、飲用水管理條例、水污染防治法及土壤地下水污染整治法","職業災害勞工保護法、勞工保險條例、就業服務法、勞資爭議處理法及性別平等工作法施行細則"],"a",
 "第3條：優先適用特定化學物質危害預防標準、有機溶劑中毒預防規則、四烷基鉛中毒預防規則、鉛中毒預防規則及粉塵危害預防標準之設置危害控制設備或措施規定；依該等法規仍未能降低暴露風險者，雇主應依本辦法設置控制設備或採取更有效之控制管理措施。第5條：有害事業廢棄物、菸草、食品藥物化粧品、製成品、民生消費商品、滅火器、製程中間產物、僅貯存無暴露之虞者不適用。",
 "Chemicals covered by the Regulations first fall under the control provisions of which laws?",
 ["The specified chemical substances standards, organic solvent rules, tetraalkyl lead rules, lead rules and dust hazard standards","The Fire Services Act and its rules, public hazardous articles regulations, the Toxic Chemicals Act, waste disposal and air pollution rules","The Building Act and technical rules, the Indoor Air Quality Act, drinking water statutes, water pollution and soil remediation rules","The Occupational Accident Protection Act, the Labor Insurance Act, the Employment Services Act, labor dispute and gender equality rules"],
 "Article 3: the five substance-specific regulations take precedence, with the Regulations adding controls where exposure remains high; Article 5 lists exclusions."),

(CA,"第6條",2,"化學品分級-頻率",
 "雇主之化學品評估及分級管理應至少每幾年執行一次？化學品種類、操作程序或製程條件變更有增加暴露風險之虞時應何時重新評估？",
 ["三年；變更前或變更後三個月內","一年；變更後一年內重新評估","五年；變更後六個月內補行辦理","每年；變更時得免再重新評估"],"a",
 "第6條：第4條之評估及分級管理至少每三年執行一次；因化學品種類操作程序或製程條件變更而有增加暴露風險之虞者，應於變更前或變更後三個月內重新評估與分級。第7條：應參照中央主管機關公告之技術指引或同等科學基礎之方法。第11條：紀錄保存三年。",
 "Chemical assessment and tiered management must be performed at least every how many years, and re-done when after a change that may increase exposure?",
 ["3 years; before the change or within 3 months after","1 year; re-assessed within one year after the change","5 years; carried out within six months after the change","Yearly; no re-assessment needed when there is a change"],
 "Article 6; Article 7: per the central technical guidance; Article 11: records kept 3 years."),

(CA,"第8條",3,"化學品分級-定量評估",
 "對於定有容許暴露標準之化學品，何種事業單位應依採樣分析方法或定量推估模式實施暴露評估？",
 ["特別危害健康作業勞工一百人以上，或總勞工人數五百人以上者","特別危害健康作業勞工三十人以上，或總勞工人數一百人以上者","從事石化製程作業勞工五十人以上，或總勞工人數三百人以上者","凡訂有作業環境監測計畫，或總勞工人數未滿三十人之事業單位"],"a",
 "第8條：中央主管機關定有容許暴露標準之化學品，事業單位從事特別危害健康作業勞工一百人以上或總勞工人數五百人以上者，雇主應依有科學根據之採樣分析方法或運用定量推估模式實施暴露評估；游離輻射作業不適用。第9條：應依作業環境監測實施辦法之監測及期程實施，必要時輔以半定量定量模式。",
 "Which enterprises must perform quantitative exposure assessment (sampling or exposure modeling) for chemicals with permissible exposure limits?",
 ["Those with 100+ workers in specially hazardous work or 500+ workers in total","Those with 30+ workers in specially hazardous work or 100+ workers in total","Those with 50+ workers in petrochemical processes or 300+ workers in total","Those with a monitoring plan in place or fewer than 30 workers in total"],
 "Article 8; Article 9 ties it to the environmental monitoring schedule."),

(CA,"第8條",3,"化學品分級-評估頻率",
 "暴露評估結果，暴露濃度低於容許暴露標準二分之一者，至少每幾年評估一次？低於標準但高於或等於二分之一者？高於或等於標準者？",
 ["三年；每年；每三個月","一年；六個月；每月","五年；三年；每年","不需；每年；每月"],"a",
 "第8條第2項：暴露濃度低於容許暴露標準二分之一者至少每三年評估一次；低於標準但高於或等於二分之一者至少每年一次；高於或等於標準者至少每三個月一次；製程變更有增加風險之虞者於變更前或後三個月內重新評估。",
 "Re-assessment frequency when exposure is below half the PEL, between half and the PEL, and at or above the PEL is:",
 ["Every 3 years; yearly; every 3 months","Yearly; every 6 months; monthly","Every 5 years; every 3 years; yearly","Never; yearly; monthly"],
 "Article 8(2): the three tiers of frequency, plus re-assessment within three months of risk-increasing changes."),

(CA,"第10條",3,"化學品分級-管理措施",
 "暴露濃度高於或等於容許暴露標準者屬第幾級管理？應採取何措施？",
 ["第三級；即採取有效控制措施並於完成改善後重新評估確保低於標準","第一級；即維持原有控制設備並於製程變更時採行變更管理即可","第二級；即就製程設備及作業程序實施檢點並採取必要之改善","第四級；即報請勞動檢查機構核准後全面停工並辦理廠址搬遷"],"a",
 "第10條：第一級（低於二分之一）持續維持原有控制並於製程變更時採變更管理；第二級（二分之一以上未達標準）就製程設備作業程序方法實施檢點並採必要改善；第三級（高於或等於標準）應即採取有效控制措施並於完成改善後重新評估確保暴露濃度低於容許暴露標準。",
 "Exposure at or above the PEL is which management level, requiring what?",
 ["Level 3; immediate effective controls and re-assessment after improvement to confirm exposure below the PEL","Level 1; keep the existing control equipment and apply management of change whenever the process is altered","Level 2; inspect the process equipment and the work procedures and make whatever improvements are needed","Level 4; report to the labor inspection agency for approval, then stop all work and relocate the plant site"],
 "Article 10: Level 1 maintain controls with management of change; Level 2 inspect and improve; Level 3 immediate controls and re-assessment."),
]
